return $input.all().map(({ json: { lead_id, raw, error } }) => ({ json: {
  lead_id,
  stage: 'parse',
  reason: 'invalid_json',
  error: String(error),
  raw
} }));

const seen = new Set();
return $input.all().map(({ json: lead }) => {
  const email = String(lead.email).trim().toLowerCase();
  let reason = null;
  if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
    reason = 'invalid_email';
  } else if (seen.has(email)) {
    reason = 'duplicate';
  } else {
    seen.add(email);
  }
  const result = {
    lead_id: lead.lead_id,
    name: lead.name,
    email,
    budget: lead.budget,
    source: lead.source,
    valid: reason === null,
    reason
  };
  if (!result.valid) result.tier = 'rejected';
  return { json: result };
});

return $input.all().map(({ json: lead }) => {
  if (lead.tier === 'rejected') return { json: { ...lead, score: 0 } };
  const budget_points = lead.budget >= 5000 ? 50 : lead.budget >= 2000 ? 30 : 10;
  const source_points = lead.source === 'referral' ? 30 : lead.source === 'web' ? 10 : 0;
  const score = budget_points + source_points;
  const tier = score >= 60 ? 'hot' : score >= 30 ? 'warm' : 'cold';
  return { json: { ...lead, budget_points, source_points, score, tier } };
});

const leads = $input.all().map(({ json: lead }) => ({
  lead_id: lead.lead_id,
  email: lead.email,
  reason: lead.reason
}));
return [{ json: { tier: 'rejected', count: leads.length, leads } }];

// Count only representations returned by successful upserts.
const summary = { created: 0, updated: 0, by_tier: {}, emails: [] };
for (const { json: response } of $input.all()) {
  summary.created += response.createdRecords.length;
  summary.updated += response.updatedRecords.length;
  for (const { fields } of response.records) {
    summary.by_tier[fields.Tier] = (summary.by_tier[fields.Tier] ?? 0) + 1;
    summary.emails.push(fields.Email);
  }
}
summary.emails.sort();
return [{ json: summary }];

// HTTP error output retains the source item and attaches error metadata.
return $input.all().map((item, index) => {
  const error = item.json.error;
  const original = item.json.lead_id ? item.json : $('Score').itemMatching(index).json;
  const message = typeof error === 'string' ? error : String(error?.message ?? error?.description ?? 'upsert_failed');
  const statusInMessage = /\b([45]\d{2})\b/.exec(message);
  return { json: {
    stage: 'upsert',
    lead_id: item.json.lead_id ?? original.lead_id,
    email: item.json.email ?? original.email,
    status: error?.statusCode ?? error?.httpCode ?? error?.status ?? item.json.statusCode ?? (statusInMessage ? Number(statusInMessage[1]) : null),
    message: message,
  } };
});
